        if(a.Length!=4)throw new ArgumentException("Usage: M303Generator <M302-report.json> <M215-report.json> <authorization.md> <output-directory>");
        string root=Root(),m302Path=Resolve(root,a[0]),m215Path=Resolve(root,a[1]),authPath=Resolve(root,a[2]),output=Resolve(root,a[3]);
