        var m302=JsonNode.Parse(File.ReadAllText(m302Path))!;var m215=JsonNode.Parse(File.ReadAllText(m215Path))!;var search=m302["search"]!;var basis=m302["basis"]!;
        double sw=N(m302["source"]?["shell_ft"]?[0]),sd=N(m302["source"]?["shell_ft"]?[1]),routeIn=N(m215["route_width_in"]);Need(sw==38.333333&&sd==40&&routeIn==36,"M302 shell or M215 route precedent changed.");
