    static End GetOuterEnd(Rect f,Rect p){if(Math.Abs(f.R-p.X)<Tol)return new(f.Id,f.X,f.Y+f.D/2,-1,0);if(Math.Abs(f.X-p.R)<Tol)return new(f.Id,f.R,f.Y+f.D/2,1,0);if(Math.Abs(f.T-p.Y)<Tol)return new(f.Id,f.X+f.W/2,f.Y,0,-1);if(Math.Abs(f.Y-p.T)<Tol)return new(f.Id,f.X+f.W/2,f.T,0,1);throw new InvalidDataException("Flight has no edge adjacent to its platform.");}
    static List<(double X,double Y)>? FindRoute(End end,Rect target,Rect[] obstacles,double sw,double sd,ref long visited){var start=new Node(0,0);var q=new Queue<Node>();var parent=new Dictionary<Node,Node?>{{start,null}};q.Enqueue(start);while(q.Count>0){var n=q.Dequeue();visited++;var p=(X:end.X+end.DX*Width/2+n.X*Grid,Y:end.Y+end.DY*Width/2+n.Y*Grid);var b=Buffer(p);if(n!=start&&TouchesEdge(b,target))return Rebuild(end,n,parent);if(n!=start&&(!Inside(b,sw,sd)||obstacles.Any(o=>Overlap(b,o))))continue;foreach(var(dX,dY)in new[]{(0,1),(1,0),(0,-1),(-1,0)}){if(n==start&&(dX!=end.DX||dY!=end.DY))continue;var next=new Node(n.X+dX,n.Y+dY);if(parent.ContainsKey(next))continue;var np=(X:end.X+end.DX*Width/2+next.X*Grid,Y:end.Y+end.DY*Width/2+next.Y*Grid);var nb=Buffer(np);if(!Inside(nb,sw,sd)||obstacles.Any(o=>Overlap(nb,o)))continue;parent[next]=n;q.Enqueue(next);}}return null;}
    static List<(double X,double Y)> Rebuild(End e,Node n,Dictionary<Node,Node?> parent){var chain=new List<Node>();Node? c=n;while(c.HasValue){chain.Add(c.Value);c=parent[c.Value];}chain.Reverse();return chain.Select(p=>(e.X+e.DX*Width/2+p.X*Grid,e.Y+e.DY*Width/2+p.Y*Grid)).ToList();}
    static Rect Buffer((double X,double Y)p)=>new("route",p.X-Width/2,p.Y-Width/2,Width,Width);static bool Inside(Rect r,double w,double d)=>r.X>=-Tol&&r.Y>=-Tol&&r.R<=w+Tol&&r.T<=d+Tol;static double Inter(Rect a,Rect b)=>Math.Max(0,Math.Min(a.R,b.R)-Math.Max(a.X,b.X))*Math.Max(0,Math.Min(a.T,b.T)-Math.Max(a.Y,b.Y));static bool Overlap(Rect a,Rect b)=>Inter(a,b)>Tol;static bool TouchesEdge(Rect a,Rect b)=>Overlap(a,b)||((Math.Abs(a.R-b.X)<Tol||Math.Abs(b.R-a.X)<Tol)&&Math.Min(a.T,b.T)-Math.Max(a.Y,b.Y)>Tol)||((Math.Abs(a.T-b.Y)<Tol||Math.Abs(b.T-a.Y)<Tol)&&Math.Min(a.R,b.R)-Math.Max(a.X,b.X)>Tol);static double Length(List<(double X,double Y)>p){double s=0;for(int i=0;i<p.Count-1;i++)s+=Math.Abs(p[i].X-p[i+1].X)+Math.Abs(p[i].Y-p[i+1].Y);return s;}
