    static string Svg(List<Attempt>a,double sw,double sd,int passed){const double k=12,p=24;var s=new StringBuilder($"<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"{F(sw*k+2*p)}\" height=\"{F(sd*k+60)}\" viewBox=\"0 0 {F(sw*k+2*p)} {F(sd*k+60)}\"><style>text{{font:10px Arial}}.shell{{fill:none;stroke:#222;stroke-width:2}}.target{{fill:#f1d9d9;stroke:#9a3030}}.route{{fill:none;stroke:#1768ac;stroke-width:5}}</style><text x=\"{p}\" y=\"14\">M303 sample route screen: {passed} of {a.Count} flight-end routes pass</text><rect class=\"shell\" x=\"{p}\" y=\"40\" width=\"{F(sw*k)}\" height=\"{F(sd*k)}\"/><text x=\"{p}\" y=\"{F(sd*k+55)}\">36-in project proxy only; no doors, end landings, or code/access finding.</text></svg>");return XDocument.Parse(s.ToString()).ToString(SaveOptions.DisableFormatting);}
    static string Hash(string p)=>Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(p)));static string Resolve(string r,string p)=>Path.GetFullPath(Path.IsPathRooted(p)?p:Path.Combine(r,p));static string Root(){for(DirectoryInfo? d=new(AppContext.BaseDirectory);d!=null;d=d.Parent)if(File.Exists(Path.Combine(d.FullName,"AGENTS.md")))return d.FullName;for(DirectoryInfo? d=new(Directory.GetCurrentDirectory());d!=null;d=d.Parent)if(File.Exists(Path.Combine(d.FullName,"AGENTS.md")))return d.FullName;throw new DirectoryNotFoundException("Root with AGENTS.md not found.");}static double N(JsonNode? n)=>n?.GetValue<double>()??throw new InvalidDataException("Expected number.");static string S(JsonNode? n)=>n?.GetValue<string>()??"";static string F(double n)=>n.ToString("0.####",CultureInfo.InvariantCulture);static void Need(bool b,string m){if(!b)throw new InvalidDataException(m);}static void Write(string p,object o)=>File.WriteAllText(p,JsonSerializer.Serialize(o,JsonOptions)+"\n",new UTF8Encoding(false));
